-- Every Australian locality and postcode with coordinates, so distance search works for any suburb.
-- Data: Matthew Proctor, Australian Postcodes (https://www.matthewproctor.com/australian_postcodes), as packaged in
-- aus-postcode-suburbs 1.3.2. Post office box and large-volume-receiver postcodes are left out.
begin;
create table public.au_postcodes(postcode char(4) not null,state text not null,latitude double precision not null,longitude double precision not null,primary key(postcode,state));
alter table public.au_postcodes enable row level security;
revoke all on public.au_postcodes from anon,authenticated;
grant select on public.au_postcodes to anon,authenticated;
create policy postcodes_read on public.au_postcodes for select to anon,authenticated using(true);
