-- A label may be a locality ("Frankston VIC"), a postcode ("3199") or both ("Frankston VIC 3199").
-- Locality wins; a postcode alone resolves through au_postcodes.
create or replace function public.jp_find_place(label text) returns table(name text,state text,latitude double precision,longitude double precision)
language sql stable security invoker set search_path='' as $$
 with parts as (select upper(coalesce(substring(label from '\m(VIC|NSW|QLD|WA|SA|TAS|ACT|NT)\M'),'')) as st,
  substring(label from '\m(\d{4})\M') as pc,
  lower(trim(regexp_replace(regexp_replace(label,'\m(VIC|NSW|QLD|WA|SA|TAS|ACT|NT|Vic|Nsw|Qld|Tas|Australia)\M|\d{4}|,',' ','gi'),'\s+',' ','g'))) as nm)
 select found.name,found.state,found.latitude,found.longitude from (
  select p.name,p.state,p.latitude,p.longitude,1 as pref from public.au_places p,parts where parts.nm<>'' and lower(p.name)=parts.nm and (parts.st='' or p.state=parts.st)
  union all
  select z.postcode::text,z.state,z.latitude,z.longitude,2 from public.au_postcodes z,parts where parts.pc is not null and z.postcode=parts.pc and (parts.st='' or z.state=parts.st)
 ) found order by pref,state limit 1
$$;
-- Re-geocode job locations that the smaller gazetteer could not place.
update public.job_locations l set (latitude,longitude)=(select p.latitude,p.longitude from public.jp_find_place(l.label) p) where l.latitude is null and exists(select 1 from public.jp_find_place(l.label));
commit;
